let raw = $json.text || '';
if (typeof raw === 'string') {
  if (raw.startsWith('```')) {
    raw = raw.replace(/^```[a-zA-Z]*\s*/, '').replace(/```\s*$/, '').trim();
  }
}

let parsed = {};
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  const match = typeof raw === 'string' ? raw.match(/\{[\s\S]*\}/) : null;
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (e2) {}
  }
}

const reqBody = $('Webhook').first().json.body || {};
const kw = reqBody.target_keyword || '';
const title = parsed.title || reqBody.title || kw;
let imgPrompt = (parsed.image_prompt_english || '').trim();

if (!imgPrompt || imgPrompt.length < 15) {
  imgPrompt = 'professional 4k photorealistic tech commercial image representing ' + kw + ', high resolution, studio lighting, cinematic, no text, no letters';
}

imgPrompt = imgPrompt.replace(/[\r\n]+/g, ' ').trim();
const seed = Math.floor(Math.random() * 999999) + 1;
const imgUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(imgPrompt) + '?width=1200&height=630&nologo=true&model=flux&seed=' + seed;

return [{
  json: {
    ...parsed,
    title: parsed.title || title,
    content_html: parsed.content_html || '',
    image_prompt_english: imgPrompt,
    image_gen_url: imgUrl,
    target_keyword: kw
  }
}];

const articleData = $('Parse & Prepare Image').first().json;
let b64 = '';

try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buffer) {
    b64 = buffer.toString('base64');
  }
} catch (e) {
  if ($input.first().binary && $input.first().binary.data) {
    b64 = $input.first().binary.data.data || '';
  }
}

const seoMeta = articleData.seo_metadata || {};
seoMeta.featured_image_b64 = b64;

return [{
  json: {
    ...articleData,
    featured_image_b64: b64,
    seo_metadata: seoMeta
  }
}];
